<?php
$bookingsFile = __DIR__.'/data/bookings.json'; $bookings = file_exists($bookingsFile) ? (json_decode(file_get_contents($bookingsFile), true) ?: []) : []; $total=count($bookings); $confirmed=count(array_filter($bookings,fn($b)=>$b['status']==='مؤكد'));
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>لوحة الإدارة | ملاعبنا</title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/style.css"><style>body{background:#f7faf5}.admin-wrap{padding:45px 0}.admin-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.admin-head h1{margin:0;font-size:30px}.back{color:#547524;text-decoration:none;font-size:13px;font-weight:700}.admin-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:25px}.admin-stat{background:#fff;border:1px solid #e4ece5;border-radius:12px;padding:20px}.admin-stat span{display:block;color:#829087;font-size:12px}.admin-stat strong{display:block;font-size:28px;margin-top:6px;color:#173c2c}.table-wrap{background:#fff;border:1px solid #e4ece5;border-radius:12px;overflow:auto}.admin-table{border-collapse:collapse;width:100%;min-width:780px;font-size:12px}.admin-table th{background:#f0f7ed;color:#5e7166;text-align:right;padding:14px}.admin-table td{border-top:1px solid #eef2ef;padding:14px}.status{color:#4c891c;background:#edf8df;border-radius:20px;padding:4px 10px;font-size:10px}.delete-btn{border:0;background:#fff0f0;color:#b25353;border-radius:5px;padding:5px 9px;font-family:inherit;font-size:11px;cursor:pointer}.no-data{text-align:center;padding:60px;color:#89958d}.admin-note{font-size:11px;color:#89958d;margin-top:15px}@media(max-width:600px){.container{width:calc(100% - 30px)}.admin-cards{grid-template-columns:1fr}.admin-head{display:block}.back{display:inline-block;margin-top:10px}}</style></head><body><header class="topbar"><div class="container nav"><a class="brand" href="index.php"><span class="brand-mark">✦</span><span>ملاعبنا</span></a><a class="back" href="index.php">← العودة إلى الموقع</a></div></header><main class="admin-wrap"><div class="container"><div class="admin-head"><div><span class="eyebrow">إدارة النظام</span><h1>الحجوزات</h1></div><button class="btn btn-primary" onclick="location.reload()">تحديث البيانات ↻</button></div><div class="admin-cards"><div class="admin-stat"><span>إجمالي الحجوزات</span><strong><?= $total ?></strong></div><div class="admin-stat"><span>الحجوزات المؤكدة</span><strong><?= $confirmed ?></strong></div><div class="admin-stat"><span>آخر تحديث</span><strong style="font-size:18px"><?= date('Y/m/d - H:i') ?></strong></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>رقم الحجز</th><th>الملعب</th><th>العميل</th><th>الجوال</th><th>الموعد</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody id="bookingsBody"><?php if(!$bookings): ?><tr><td colspan="7" class="no-data">لا توجد حجوزات حتى الآن.</td></tr><?php else: foreach(array_reverse($bookings) as $b): ?><tr data-id="<?= htmlspecialchars($b['id']) ?>"><td><?= htmlspecialchars($b['id']) ?></td><td><strong><?= htmlspecialchars($b['field_name']) ?></strong></td><td><?= htmlspecialchars($b['customer_name']) ?></td><td><?= htmlspecialchars($b['phone']) ?></td><td><?= htmlspecialchars($b['booking_date']) ?><br><?= htmlspecialchars($b['booking_time']) ?></td><td><span class="status"><?= htmlspecialchars($b['status']) ?></span></td><td><button class="delete-btn" onclick="deleteBooking('<?= htmlspecialchars($b['id'], ENT_QUOTES) ?>')">إلغاء</button></td></tr><?php endforeach; endif; ?></tbody></table></div><p class="admin-note">هذه لوحة إدارة تجريبية بدون نظام تسجيل دخول. أضف المصادقة قبل استخدامها في بيئة إنتاجية.</p></div></main><script>async function deleteBooking(id){if(!confirm('هل تريد إلغاء هذا الحجز؟'))return;const r=await fetch('api.php',{method:'DELETE',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'id='+encodeURIComponent(id)});const d=await r.json();if(d.success)location.reload();else alert(d.message)}</script></body></html>
